using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A not-found answer used as a position, in Python, Java, C#, JavaScript, TypeScript, Go, C, C++, Rust, Ruby, PHP, Lua,
/// Perl, Dart, PowerShell, Scala and Fortran: find answers -1 when the name is not there, and the caller reads names at its
/// answer. Left alone: the answer checked before the read in each language, the answer printed rather than read at, a check
/// of -1 before the read, the answer handed to another function, and a comparison's -1 used in arithmetic.
/// </summary>
public class NotFoundAsPositionTests
{
    private static IReadOnlyList<LogicFinding> Scanned(string fileName, string code) =>
        LogicPatterns.Scan(new SourceFile { Path = Path.Combine(Path.GetTempPath(), fileName), Lines = code.Replace("\r\n", "\n").Split('\n') })
            .Where(finding => finding.PatternId.EndsWith("-not-found-as-position", StringComparison.Ordinal))
            .ToList();

    /// <summary>The file, the program, and what the check said of it here: the finding's line, check and words.</summary>
    public static TheoryData<string, string, string> Found => new()
    {
        { "find.c", "#include <stdio.h>\n#include <string.h>\n\nint find(const char *items[], int count, const char *wanted) {\n    for (int index = 0; index < count; index++) {\n        if (strcmp(items[index], wanted) == 0) {\n            return index;\n        }\n    }\n    return -1;\n}\n\nint main(void) {\n    const char *names[] = {\"ann\", \"bob\", \"cat\"};\n    int place = find(names, 3, \"dan\");\n    printf(\"%s\\n\", names[place]);\n    return 0;\n}\n", "16|logic-c-not-found-as-position|`find` answers -1 when it finds nothing, and its answer from line 15 is used as a position in `names` with nothing checking for -1 first - C reads before the start of the list, which it leaves undefined" },
        { "find.cpp", "#include <iostream>\n#include <string>\n#include <vector>\n\nint find(const std::vector<std::string>& items, const std::string& wanted) {\n    for (int index = 0; index < static_cast<int>(items.size()); index++) {\n        if (items[index] == wanted) {\n            return index;\n        }\n    }\n    return -1;\n}\n\nint main() {\n    std::vector<std::string> names = {\"ann\", \"bob\", \"cat\"};\n    int place = find(names, \"dan\");\n    std::cout << names.at(place) << \"\\n\";\n}\n", "17|logic-cpp-not-found-as-position|`find` answers -1 when it finds nothing, and its answer from line 16 is used as a position in `names` with nothing checking for -1 first - C++ stops with out_of_range where the list is read with at, and reads before its start with []" },
        { "Find.cs", "using System;\n\nstring[] names = { \"ann\", \"bob\", \"cat\" };\nint place = Find(names, \"dan\");\nConsole.WriteLine(names[place]);\n\nstatic int Find(string[] items, string wanted)\n{\n    for (int index = 0; index < items.Length; index++)\n    {\n        if (items[index] == wanted)\n        {\n            return index;\n        }\n    }\n    return -1;\n}\n", "5|logic-csharp-not-found-as-position|`Find` answers -1 when it finds nothing, and its answer from line 4 is used as a position in `names` with nothing checking for -1 first - C# stops with IndexOutOfRangeException" },
        { "find.dart", "int find(List<String> items, String wanted) {\n  for (var index = 0; index < items.length; index++) {\n    if (items[index] == wanted) {\n      return index;\n    }\n  }\n  return -1;\n}\n\nvoid main() {\n  final names = ['ann', 'bob', 'cat'];\n  final place = find(names, 'dan');\n  print(names[place]);\n}\n", "13|logic-dart-not-found-as-position|`find` answers -1 when it finds nothing, and its answer from line 12 is used as a position in `names` with nothing checking for -1 first - Dart stops with a RangeError" },
        { "find.f90", "program main\n  implicit none\n  character(len=3) :: names(3) = [character(len=3) :: \"ann\", \"bob\", \"cat\"]\n  integer :: place\n  place = find(names, \"dan\")\n  print *, names(place)\ncontains\n  integer function find(items, wanted)\n    character(len=*), intent(in) :: items(:), wanted\n    integer :: index\n    do index = 1, size(items)\n      if (items(index) == wanted) then\n        find = index\n        return\n      end if\n    end do\n    find = -1\n  end function find\nend program main\n", "6|logic-fortran-not-found-as-position|`find` answers -1 when it finds nothing, and its answer from line 5 is used as a position in `names` with nothing checking for -1 first - Fortran reads outside the array - built with bounds checked it stops, and without, it reads whatever is there" },
        { "find.go", "package main\n\nimport \"fmt\"\n\nfunc find(items []string, wanted string) int {\n\tfor index, item := range items {\n\t\tif item == wanted {\n\t\t\treturn index\n\t\t}\n\t}\n\treturn -1\n}\n\nfunc main() {\n\tnames := []string{\"ann\", \"bob\", \"cat\"}\n\tplace := find(names, \"dan\")\n\tfmt.Println(names[place])\n}\n", "17|logic-go-not-found-as-position|`find` answers -1 when it finds nothing, and its answer from line 16 is used as a position in `names` with nothing checking for -1 first - Go stops with index out of range [-1]" },
        { "Find.java", "public class Find {\n    static int find(String[] items, String wanted) {\n        for (int index = 0; index < items.length; index++) {\n            if (items[index].equals(wanted)) {\n                return index;\n            }\n        }\n        return -1;\n    }\n\n    public static void main(String[] args) {\n        String[] names = {\"ann\", \"bob\", \"cat\"};\n        int place = find(names, \"dan\");\n        System.out.println(names[place]);\n    }\n}\n", "14|logic-java-not-found-as-position|`find` answers -1 when it finds nothing, and its answer from line 13 is used as a position in `names` with nothing checking for -1 first - Java stops with ArrayIndexOutOfBoundsException" },
        { "find.js", "function find(items, wanted) {\n  for (let index = 0; index < items.length; index++) {\n    if (items[index] === wanted) {\n      return index;\n    }\n  }\n  return -1;\n}\n\nconst names = [\"ann\", \"bob\", \"cat\"];\nconst place = find(names, \"dan\");\nconsole.log(names[place]);\n", "12|logic-js-not-found-as-position|`find` answers -1 when it finds nothing, and its answer from line 11 is used as a position in `names` with nothing checking for -1 first - JavaScript reads -1 as a key the list does not have, and gives undefined" },
        { "find.lua", "local function find(items, wanted)\n  for index, item in ipairs(items) do\n    if item == wanted then\n      return index\n    end\n  end\n  return -1\nend\n\nlocal names = {\"ann\", \"bob\", \"cat\"}\nlocal place = find(names, \"dan\")\nprint(names[place])\n", "12|logic-lua-not-found-as-position|`find` answers -1 when it finds nothing, and its answer from line 11 is used as a position in `names` with nothing checking for -1 first - Lua reads -1 as a key the table does not have, and gives nil" },
        { "find.php", "<?php\nfunction find(array $items, string $wanted): int\n{\n    foreach ($items as $index => $item) {\n        if ($item === $wanted) {\n            return $index;\n        }\n    }\n    return -1;\n}\n\n$names = [\"ann\", \"bob\", \"cat\"];\n$place = find($names, \"dan\");\necho $names[$place], PHP_EOL;\n", "14|logic-php-not-found-as-position|`find` answers -1 when it finds nothing, and its answer from line 13 is used as a position in `$names` with nothing checking for -1 first - PHP warns of a key the array does not have, and gives null" },
        { "find.pl", "use strict;\nuse warnings;\n\nsub find {\n    my ($items, $wanted) = @_;\n    for my $index (0 .. $#$items) {\n        return $index if $items->[$index] eq $wanted;\n    }\n    return -1;\n}\n\nmy @names = (\"ann\", \"bob\", \"cat\");\nmy $place = find(\\@names, \"dan\");\nprint $names[$place], \"\\n\";\n", "14|logic-perl-not-found-as-position|`find` answers -1 when it finds nothing, and its answer from line 13 is used as a position in `names` with nothing checking for -1 first - Perl reads -1 as the last item, so the last one is used as if it were found" },
        { "find.ps1", "function Find-Name($items, $wanted) {\n    for ($index = 0; $index -lt $items.Count; $index++) {\n        if ($items[$index] -eq $wanted) {\n            return $index\n        }\n    }\n    return -1\n}\n\n$names = @(\"ann\", \"bob\", \"cat\")\n$place = Find-Name $names \"dan\"\n$names[$place]\n", "12|logic-powershell-not-found-as-position|`Find-Name` answers -1 when it finds nothing, and its answer from line 11 is used as a position in `$names` with nothing checking for -1 first - PowerShell reads -1 as the last item, so the last one is used as if it were found" },
        { "find.py", "def find(items, wanted):\n    for index in range(len(items)):\n        if items[index] == wanted:\n            return index\n    return -1\n\n\nnames = [\"ann\", \"bob\", \"cat\"]\nplace = find(names, \"dan\")\nprint(names[place])\n", "10|logic-python-not-found-as-position|`find` answers -1 when it finds nothing, and its answer from line 9 is used as a position in `names` with nothing checking for -1 first - Python reads -1 as the last item, so the last one is used as if it were found" },
        { "find.rb", "def find(items, wanted)\n  items.each_with_index do |item, index|\n    return index if item == wanted\n  end\n  -1\nend\n\nnames = [\"ann\", \"bob\", \"cat\"]\nplace = find(names, \"dan\")\nputs names[place]\n", "10|logic-ruby-not-found-as-position|`find` answers -1 when it finds nothing, and its answer from line 9 is used as a position in `names` with nothing checking for -1 first - Ruby reads -1 as the last item, so the last one is used as if it were found" },
        { "find.rs", "fn find(items: &[&str], wanted: &str) -> i32 {\n    for index in 0..items.len() {\n        if items[index] == wanted {\n            return index as i32;\n        }\n    }\n    -1\n}\n\nfn main() {\n    let names = [\"ann\", \"bob\", \"cat\"];\n    let place = find(&names, \"dan\");\n    println!(\"{}\", names[place as usize]);\n}\n", "13|logic-rust-not-found-as-position|`find` answers -1 when it finds nothing, and its answer from line 12 is used as a position in `names` with nothing checking for -1 first - Rust stops with an index out of bounds, as -1 made a position is the largest there is" },
        { "Find.scala", "object Find {\n  def find(items: Array[String], wanted: String): Int = {\n    for (index <- items.indices) {\n      if (items(index) == wanted) {\n        return index\n      }\n    }\n    -1\n  }\n\n  def main(args: Array[String]): Unit = {\n    val names = Array(\"ann\", \"bob\", \"cat\")\n    val place = find(names, \"dan\")\n    println(names(place))\n  }\n}\n", "14|logic-scala-not-found-as-position|`find` answers -1 when it finds nothing, and its answer from line 13 is used as a position in `names` with nothing checking for -1 first - Scala stops with ArrayIndexOutOfBoundsException" },
        { "find.ts", "function find(items: string[], wanted: string): number {\n  for (let index = 0; index < items.length; index++) {\n    if (items[index] === wanted) {\n      return index;\n    }\n  }\n  return -1;\n}\n\nconst names: string[] = [\"ann\", \"bob\", \"cat\"];\nconst place = find(names, \"dan\");\nconsole.log(names[place]);\n", "12|logic-js-not-found-as-position|`find` answers -1 when it finds nothing, and its answer from line 11 is used as a position in `names` with nothing checking for -1 first - JavaScript reads -1 as a key the list does not have, and gives undefined" },
    };

    /// <summary>The file, and a program the check must leave alone: each found program put right, and the near misses.</summary>
